@@ -387,6 +387,30 @@ type batchInternal struct {
 	// variable may violate memory safety. Since we don't use atomics here,
 	// false negatives are possible.
 	committing bool
+
+	commitJobID         int
+	commitCorrelationID uint64
+	syncWAL             bool
+	durableOnce         sync.Once
+}
+
+func (b *Batch) signalDurable(d *DB, err error, applyDur, syncDur time.Duration) {
+	if !b.syncWAL || d == nil {
+		return
+	}
+	b.durableOnce.Do(func() {
+		info := BatchDurableInfo{
+			JobID:         b.commitJobID,
+			SeqNum:        b.SeqNum(),
+			Err:           err,
+			ApplyDuration: applyDur,
+			SyncDuration:  syncDur,
+			CorrelationID: b.commitCorrelationID,
+			BatchSize:     len(b.Repr()),
+			KeyCount:      uint32(b.Count()),
+		}
+		d.onBatchDurable(info)
+	})
 }

