diff --git a/durability.go b/durability.go
new file mode 100644
index 00000000..6b69198d
--- /dev/null
+++ b/durability.go
@@ -0,0 +1,393 @@
+// Copyright 2024 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"sync"
+	"sync/atomic"
+	"time"
+
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+)
+
+// DurabilityStats holds a snapshot of durability-related metrics.
+type DurabilityStats struct {
+	HighestDurableSeqNum   base.SeqNum
+	FirstErr               error
+	PendingWaiters         int64
+	TotalDurableCommits    uint64
+	TotalFailedCommits     uint64
+	CumulativeSyncDuration time.Duration
+	MaxSyncDuration        time.Duration
+}
+
+type jobDurabilityState struct {
+	jobID  int
+	seqNum base.SeqNum
+	err    error
+	done   bool
+}
+
+type durabilitySub struct {
+	seq base.SeqNum
+	ch  chan error
+}
+
+type durabilityManager struct {
+	mu struct {
+		sync.Mutex
+		highestDurableSeqNum base.SeqNum
+		firstErr             error
+		totalDurableCommits  uint64
+		totalFailedCommits   uint64
+		cumulativeSyncDur    time.Duration
+		maxSyncDur           time.Duration
+
+		retainedJobs map[int]*jobDurabilityState
+		minJobID     int
+		maxJobID     int
+
+		subscriptions []durabilitySub
+		notifyCh      chan struct{}
+	}
+	pendingWaiters atomic.Int64
+	nextJobID      atomic.Int64
+}
+
+const maxJobRetentionWindow = 10000
+const maxDurabilitySubscriptions = 4096
+
+func (dm *durabilityManager) init() {
+	dm.mu.retainedJobs = make(map[int]*jobDurabilityState)
+	dm.mu.notifyCh = make(chan struct{})
+}
+
+func (d *DB) registerPendingJob() int {
+	jobID := int(d.durability.nextJobID.Add(1))
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+
+	if jobID > d.durability.mu.maxJobID {
+		d.durability.mu.maxJobID = jobID
+	}
+	if d.durability.mu.minJobID == 0 {
+		d.durability.mu.minJobID = jobID
+	}
+	js := &jobDurabilityState{jobID: jobID}
+	d.durability.mu.retainedJobs[jobID] = js
+
+	if len(d.durability.mu.retainedJobs) > maxJobRetentionWindow {
+		targetMin := d.durability.mu.maxJobID - maxJobRetentionWindow + 1
+		for jID := range d.durability.mu.retainedJobs {
+			if jID < targetMin {
+				delete(d.durability.mu.retainedJobs, jID)
+			}
+		}
+		d.durability.mu.minJobID = targetMin
+	}
+	return jobID
+}
+
+func (d *DB) onBatchDurable(info BatchDurableInfo) {
+	d.durability.mu.Lock()
+
+	if info.Err != nil {
+		d.durability.mu.totalFailedCommits++
+		if d.durability.mu.firstErr == nil {
+			d.durability.mu.firstErr = info.Err
+		}
+	} else {
+		d.durability.mu.totalDurableCommits++
+		d.durability.mu.cumulativeSyncDur += info.SyncDuration
+		if info.SyncDuration > d.durability.mu.maxSyncDur {
+			d.durability.mu.maxSyncDur = info.SyncDuration
+		}
+		highest := info.SeqNum
+		if info.KeyCount > 0 {
+			highest += base.SeqNum(info.KeyCount - 1)
+		}
+		if highest > d.durability.mu.highestDurableSeqNum {
+			d.durability.mu.highestDurableSeqNum = highest
+		}
+	}
+
+	if js, ok := d.durability.mu.retainedJobs[info.JobID]; ok {
+		js.err = info.Err
+		js.seqNum = info.SeqNum
+		js.done = true
+	}
+
+	if len(d.durability.mu.subscriptions) > 0 {
+		totalCommits := d.durability.mu.totalDurableCommits + d.durability.mu.totalFailedCommits
+		remaining := d.durability.mu.subscriptions[:0]
+		for _, sub := range d.durability.mu.subscriptions {
+			durable := (sub.seq == 0 && totalCommits > 0) || (sub.seq > 0 && d.durability.mu.highestDurableSeqNum >= sub.seq)
+			err := d.durability.mu.firstErr
+			if durable && err == nil {
+				sub.ch <- nil
+			} else if err != nil {
+				sub.ch <- err
+			} else {
+				remaining = append(remaining, sub)
+			}
+		}
+		d.durability.mu.subscriptions = remaining
+	}
+
+	oldNotifyCh := d.durability.mu.notifyCh
+	d.durability.mu.notifyCh = make(chan struct{})
+	close(oldNotifyCh)
+
+	d.durability.mu.Unlock()
+
+	if d.opts.EventListener != nil && d.opts.EventListener.BatchDurable != nil {
+		d.opts.EventListener.BatchDurable(info)
+	}
+
+	if d.batchDurableConfigured {
+		d.durableCommitCount.Add(1)
+		d.durableCommitDuration.Add(uint64(info.SyncDuration))
+	}
+}
+
+func (d *DB) closeDurability(err error) {
+	d.durability.mu.Lock()
+	if d.durability.mu.firstErr == nil {
+		d.durability.mu.firstErr = err
+	}
+	for _, sub := range d.durability.mu.subscriptions {
+		sub.ch <- err
+	}
+	d.durability.mu.subscriptions = nil
+
+	oldNotifyCh := d.durability.mu.notifyCh
+	d.durability.mu.notifyCh = make(chan struct{})
+	close(oldNotifyCh)
+
+	d.durability.mu.Unlock()
+}
+
+// DurableState returns the highest durable sequence number and first latched error.
+func (d *DB) DurableState() (base.SeqNum, error) {
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+	return d.durability.mu.highestDurableSeqNum, d.durability.mu.firstErr
+}
+
+// DurabilityStats returns a snapshot of durability statistics.
+func (d *DB) DurabilityStats() DurabilityStats {
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+	return DurabilityStats{
+		HighestDurableSeqNum:   d.durability.mu.highestDurableSeqNum,
+		FirstErr:               d.durability.mu.firstErr,
+		PendingWaiters:         d.durability.pendingWaiters.Load(),
+		TotalDurableCommits:    d.durability.mu.totalDurableCommits,
+		TotalFailedCommits:     d.durability.mu.totalFailedCommits,
+		CumulativeSyncDuration: d.durability.mu.cumulativeSyncDur,
+		MaxSyncDuration:        d.durability.mu.maxSyncDur,
+	}
+}
+
+// WaitForDurability blocks until sequence number seq is durable. Zero succeeds after any commit.
+func (d *DB) WaitForDurability(seq base.SeqNum) error {
+	return d.WaitForDurabilityContext(context.Background(), seq)
+}
+
+// WaitForDurabilityContext blocks until sequence number seq is durable. Zero succeeds after any commit.
+func (d *DB) WaitForDurabilityContext(ctx context.Context, seq base.SeqNum) error {
+	if d.opts.DisableWAL {
+		return nil
+	}
+	d.durability.pendingWaiters.Add(1)
+	defer d.durability.pendingWaiters.Add(-1)
+
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+
+	for {
+		totalCommits := d.durability.mu.totalDurableCommits + d.durability.mu.totalFailedCommits
+		if seq == 0 && totalCommits > 0 {
+			if d.durability.mu.firstErr != nil {
+				return d.durability.mu.firstErr
+			}
+			return nil
+		}
+		if seq > 0 && d.durability.mu.highestDurableSeqNum >= seq {
+			return nil
+		}
+		if d.durability.mu.firstErr != nil {
+			return d.durability.mu.firstErr
+		}
+		if d.closed.Load() != nil {
+			return ErrClosed
+		}
+
+		select {
+		case <-ctx.Done():
+			return ctx.Err()
+		default:
+		}
+
+		ch := d.durability.mu.notifyCh
+		d.durability.mu.Unlock()
+
+		select {
+		case <-ch:
+			d.durability.mu.Lock()
+		case <-ctx.Done():
+			d.durability.mu.Lock()
+			totalCommits = d.durability.mu.totalDurableCommits + d.durability.mu.totalFailedCommits
+			if seq == 0 && totalCommits > 0 {
+				if d.durability.mu.firstErr != nil {
+					return d.durability.mu.firstErr
+				}
+				return nil
+			}
+			if seq > 0 && d.durability.mu.highestDurableSeqNum >= seq {
+				return nil
+			}
+			if d.durability.mu.firstErr != nil {
+				return d.durability.mu.firstErr
+			}
+			if d.closed.Load() != nil {
+				return ErrClosed
+			}
+			return ctx.Err()
+		}
+	}
+}
+
+// WaitForDurabilityBatch blocks until every sequence number in seqs is durable.
+func (d *DB) WaitForDurabilityBatch(seqs []base.SeqNum) error {
+	return d.WaitForDurabilityBatchContext(context.Background(), seqs)
+}
+
+// WaitForDurabilityBatchContext blocks until every sequence number in seqs is durable.
+func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqs []base.SeqNum) error {
+	if len(seqs) == 0 {
+		return nil
+	}
+	var maxSeq base.SeqNum
+	for _, s := range seqs {
+		if s > maxSeq {
+			maxSeq = s
+		}
+	}
+	return d.WaitForDurabilityContext(ctx, maxSeq)
+}
+
+// WaitForJobDurability blocks until the given job ID is durable.
+func (d *DB) WaitForJobDurability(jobID int) error {
+	return d.WaitForJobDurabilityContext(context.Background(), jobID)
+}
+
+// WaitForJobDurabilityContext blocks until the given job ID is durable.
+func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
+	if d.opts.DisableWAL {
+		return nil
+	}
+	d.durability.pendingWaiters.Add(1)
+	defer d.durability.pendingWaiters.Add(-1)
+
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+
+	for {
+		if jobID <= 0 || jobID > d.durability.mu.maxJobID {
+			return errors.Errorf("pebble: unknown job ID %d", jobID)
+		}
+		if jobID < d.durability.mu.minJobID {
+			return errors.Errorf("pebble: expired job ID %d", jobID)
+		}
+
+		js, ok := d.durability.mu.retainedJobs[jobID]
+		if !ok {
+			return errors.Errorf("pebble: expired job ID %d", jobID)
+		}
+
+		if js.done {
+			if js.err != nil {
+				return js.err
+			}
+			return nil
+		}
+		if d.durability.mu.firstErr != nil {
+			return d.durability.mu.firstErr
+		}
+		if d.closed.Load() != nil {
+			return ErrClosed
+		}
+
+		select {
+		case <-ctx.Done():
+			return ctx.Err()
+		default:
+		}
+
+		ch := d.durability.mu.notifyCh
+		d.durability.mu.Unlock()
+
+		select {
+		case <-ch:
+			d.durability.mu.Lock()
+		case <-ctx.Done():
+			d.durability.mu.Lock()
+			if js.done {
+				return js.err
+			}
+			if d.durability.mu.firstErr != nil {
+				return d.durability.mu.firstErr
+			}
+			if d.closed.Load() != nil {
+				return ErrClosed
+			}
+			return ctx.Err()
+		}
+	}
+}
+
+// DurabilityNotify returns a channel that delivers nil on success or non-nil error on WAL sync failure or DB close.
+func (d *DB) DurabilityNotify(seq base.SeqNum) <-chan error {
+	ch := make(chan error, 1)
+	if d.opts.DisableWAL {
+		ch <- nil
+		return ch
+	}
+
+	d.durability.mu.Lock()
+	defer d.durability.mu.Unlock()
+
+	totalCommits := d.durability.mu.totalDurableCommits + d.durability.mu.totalFailedCommits
+	if (seq == 0 && totalCommits > 0) || (seq > 0 && d.durability.mu.highestDurableSeqNum >= seq) {
+		if d.durability.mu.firstErr != nil {
+			ch <- d.durability.mu.firstErr
+		} else {
+			ch <- nil
+		}
+		return ch
+	}
+	if d.durability.mu.firstErr != nil {
+		ch <- d.durability.mu.firstErr
+		return ch
+	}
+	if d.closed.Load() != nil {
+		ch <- ErrClosed
+		return ch
+	}
+
+	if len(d.durability.mu.subscriptions) >= maxDurabilitySubscriptions {
+		ch <- errors.New("pebble: durability notify subscription limit exceeded")
+		return ch
+	}
+
+	d.durability.mu.subscriptions = append(d.durability.mu.subscriptions, durabilitySub{
+		seq: seq,
+		ch:  ch,
+	})
+	return ch
+}
